INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24001, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "アヤネ", 401, 2, 0.0, 0.0, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 102301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24002, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "アヤネ", 402, 2, 0.0, 2.21, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 102301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24003, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "アヤネ", 403, 2, 0.0, 0.0, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 102301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24004, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "アサヒ", 701, 1, 0.0, 1.99, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 192201, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24005, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "アサヒ", 702, 2, 0.0, 2.21, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 192201, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24006, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "アサヒ", 703, 1, 0.0, 3.33, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 192201, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24007, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "部員３", 801, 2, 0.0, 0.0, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 192301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24008, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "部員３", 802, 2, 0.0, 2.68, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 192301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24009, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "部員３", 803, 2, 0.0, 0.0, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 192301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24010, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "", 501, 1, 0.0, 0.0, "やった！", 192501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24011, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "", 502, 1, 0.0, 0.0, "勝ったよ！", 192501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24012, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "", 503, 1, 0.0, 0.0, "いい調子！", 192501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24013, 0.0, "2020/07/31 12:00:00", 6, "2030/12/17 14:59:59", "ミサト", 111, 2, 0.0, 5.33, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24014, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ミサト", 112, 2, 0.0, 6.85, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24015, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ミサト", 113, 2, 0.0, 3.0, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24016, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ダイチ", 611, 2, 0.0, 6.11, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 192401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24017, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ダイチ", 612, 2, 0.0, 6.75, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 192401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24018, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "ダイチ", 613, 2, 0.0, 0.0, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 192401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24019, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "ハツネ", 211, 1, 0.0, 4.52, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 113401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24020, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "ハツネ", 212, 1, 0.0, 3.89, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 113401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24021, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ハツネ", 213, 2, 0.0, 13.49, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 113401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24022, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "カヤ", 311, 2, 0.0, 3.17, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 106501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24023, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "カヤ", 312, 2, 0.0, 4.42, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 106501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24024, 0.0, "2020/07/31 12:00:00", 6, "2030/12/17 14:59:59", "カヤ", 313, 1, 0.0, 2.89, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 106501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24025, 0.0, "2020/07/31 12:00:00", 4, "2030/12/17 14:59:59", "アヤネ", 421, 3, 0.0, 3.71, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 102301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24026, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "アサヒ", 721, 1, 0.0, 5.1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 192201, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24027, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "部員３", 821, 3, 0.0, 4.34, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 192301, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24028, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "", 521, 1, 0.0, 0.0, "いい勝負だったよ\nまたやろうね", 192501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24029, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ミサト", 101, 2, -360.0, 5.62, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24030, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ミサト", 102, 2, -360.0, 9.58, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24031, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "ミサト", 103, 2, -360.0, 0.0, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24032, 0.0, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "ミサト", 104, 1, -360.0, 9.13, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 113501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 24033, 0.0, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "ミサト", 105, 2, -360.0, 8.27, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 113501, 10046);
